INSERT INTO recipes (title, servings, method, notes, category, category_source) VALUES
  ('Full English breakfast (sample)', 10, 'Grill the sausages and bacon. Roast the halved tomatoes and mushrooms with a little oil. Warm the beans. Fry or scramble the eggs to order and serve with buttered toast.', 'Sample recipe for testing the app.', 'brunch', 'chef'),
  ('Shakshuka with feta and flatbreads (sample)', 10, 'Soften the onions and peppers in oil, add garlic and spices, then the tomatoes. Simmer 20 minutes until thick. Make wells, crack in the eggs, cover and cook until just set. Finish with feta and coriander. Serve with warm flatbreads.', 'Sample recipe for testing the app.', 'brunch', 'chef'),
  ('Overnight oats with berries (sample)', 10, 'The night before, mix the oats, chia, milk and yoghurt in a large tub and chill. In the morning loosen with a splash of milk, top with the berries (thawed) and a drizzle of honey.', 'Sample recipe for testing the app.', 'brunch', 'chef'),
  ('Hummus with crudités (sample)', 10, 'Blend the drained chickpeas with tahini, lemon juice, garlic, oil and a splash of cold water until smooth. Season. Cut the carrots, cucumber and peppers into sticks and serve alongside.', 'Sample recipe for testing the app.', 'snack', 'chef'),
  ('Flapjacks (sample)', 16, 'Melt the butter, sugar and syrup together. Stir in the oats. Press into a lined tray and bake at 180°C for 20 to 25 minutes until golden at the edges. Cool in the tray, then cut into 16.', 'Sample recipe for testing the app.', 'snack', 'chef'),
  ('Banana and walnut bread (sample)', 10, 'Cream the butter and sugar, beat in the eggs, then the mashed bananas. Fold in the flour, bicarb and chopped walnuts. Bake in a lined loaf tin at 170°C for about an hour, until a skewer comes out clean.', 'Sample recipe for testing the app.', 'snack', 'chef'),
  ('Beef and ale stew with mash (sample)', 10, 'Toss the beef in flour and brown in batches. Soften the onions, carrots and celery, add the beef back with the ale, stock, tomato puree and thyme. Cover and cook at 160°C for 2.5 hours. Boil the potatoes and mash with butter and hot milk.', 'Sample recipe for testing the app.', 'dinner', 'chef'),
  ('Chicken tikka masala with rice (sample)', 10, 'Marinate the chicken in yoghurt and half the paste for a few hours, then grill until charred. Fry the onion, garlic and ginger, add the rest of the paste and the tomatoes and simmer 15 minutes. Add the chicken and cream and simmer 10 minutes more. Serve with rice and coriander.', 'Sample recipe for testing the app.', 'dinner', 'chef'),
  ('Baked salmon with new potatoes and green beans (sample)', 10, 'Halve and boil the new potatoes, then toss with butter and dill. Lay the salmon on lined trays, season, add lemon slices and a drizzle of oil and bake at 200°C for 12 to 15 minutes. Blanch the green beans for 3 minutes.', 'Sample recipe for testing the app.', 'dinner', 'chef'),
  ('Big green salad (sample)', 10, 'Whisk the oil, vinegar and mustard with a pinch of salt. Toss the leaves, cucumber and halved tomatoes with the dressing just before serving.', 'Sample recipe for testing the app.', 'side', 'chef');

INSERT INTO recipe_alternatives (recipe_id, label, notes)
SELECT r.id, v.column2, v.column3 FROM (VALUES
  ('Full English breakfast (sample)', 'Vegan', 'Tofu scramble instead of eggs.'),
  ('Shakshuka with feta and flatbreads (sample)', 'Gluten-free, dairy-free', 'No feta, gluten-free toast instead of flatbread.'),
  ('Overnight oats with berries (sample)', 'Vegan, gluten-free', 'Gluten-free oats, oat milk, coconut yoghurt and maple syrup.'),
  ('Flapjacks (sample)', 'Vegan, gluten-free', 'Dairy-free spread and gluten-free oats. Bake on a separate tray.'),
  ('Banana and walnut bread (sample)', 'Gluten-free, nut-free', 'Gluten-free flour and no walnuts. Bake in a separate tin.'),
  ('Beef and ale stew with mash (sample)', 'Vegan', 'Mushroom and lentil stew, mash made with oat milk and spread. Brown ale is often not vegan: check the label.'),
  ('Chicken tikka masala with rice (sample)', 'Vegan', 'Chickpea and cauliflower curry with coconut milk. Check the paste is vegan.'),
  ('Baked salmon with new potatoes and green beans (sample)', 'Dairy-free', 'Olive oil on the potatoes instead of butter.')
) v JOIN recipes r ON r.title = v.column1;

