SELECT r.id, a.id, 'vegetarian', v.column3, 'chef' FROM v JOIN recipes r ON r.title = v.column1 LEFT JOIN recipe_alternatives a ON a.recipe_id = r.id AND a.label = v.column2
UNION ALL SELECT r.id, a.id, 'vegan', v.column4, 'chef' FROM v JOIN recipes r ON r.title = v.column1 LEFT JOIN recipe_alternatives a ON a.recipe_id = r.id AND a.label = v.column2
UNION ALL SELECT r.id, a.id, 'gluten_free', v.column5, 'chef' FROM v JOIN recipes r ON r.title = v.column1 LEFT JOIN recipe_alternatives a ON a.recipe_id = r.id AND a.label = v.column2
UNION ALL SELECT r.id, a.id, 'dairy_free', v.column6, 'chef' FROM v JOIN recipes r ON r.title = v.column1 LEFT JOIN recipe_alternatives a ON a.recipe_id = r.id AND a.label = v.column2
UNION ALL SELECT r.id, a.id, 'contains_nuts', v.column7, 'chef' FROM v JOIN recipes r ON r.title = v.column1 LEFT JOIN recipe_alternatives a ON a.recipe_id = r.id AND a.label = v.column2;
